namespace jxx::awt::geom { ::jxx::lang::jdouble Line2D::ptSegDistSq(::jxx::lang::jdouble x1,::jxx::lang::jdouble y1,::jxx::lang::jdouble x2,::jxx::lang::jdouble y2,::jxx::lang::jdouble px,::jxx::lang::jdouble py){auto dx=x2-x1,dy=y2-y1;if(dx==0&&dy==0){dx=px-x1;dy=py-y1;return dx*dx+dy*dy;}auto t=((px-x1)*dx+(py-y1)*dy)/(dx*dx+dy*dy);t=std::max(0.0,std::min(1.0,t));dx=px-(x1+t*dx);dy=py-(y1+t*dy);return dx*dx+dy*dy;} ::jxx::lang::jdouble Line2D::ptSegDist(::jxx::lang::jdouble x,::jxx::lang::jdouble y)const{return std::sqrt(ptSegDistSq(getX1(),getY1(),getX2(),getY2(),x,y));} ::jxx::Ptr<Rectangle2D> Line2D::getBounds2D()const{auto x=std::min(getX1(),getX2()),y=std::min(getY1(),getY2());return ::jxx::NEW<Rectangle2D::Double>(x,y,std::abs(getX2()-getX1()),std::abs(getY2()-getY1()));} ::jxx::Ptr<::jxx::awt::Rectangle> Line2D::getBounds()const{return getBounds2D()->getBounds();} ::jxx::lang::jbool Line2D::intersects(::jxx::lang::jdouble x,::jxx::lang::jdouble y,::jxx::lang::jdouble w,::jxx::lang::jdouble h)const{return getBounds2D()->intersects(x,y,w,h);} ::jxx::lang::jbool Line2D::intersects(const ::jxx::Ptr<Rectangle2D>&r)const{return r&&intersects(r->getX(),r->getY(),r->getWidth(),r->getHeight());} }
